@import url("https://fonts.googleapis.com/css2?family=Poppins:wght@100;200;300;400;500;600;700;800;900&display=swap");

*{
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: "Poppins",sans-serif;
}

body{
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100vh;
    width: 100%;
    background: linear-gradient(to top right, rgb(0, 0, 53), rgba(18, 18, 121, 0.89) );
}


.clock {
    display: flex;
    align-items: center;
    justify-content: space-evenly;
    flex-direction: column;
    background: rgba(255, 255, 255, 0.1);
    width: 480px;
    height: 140px;
    color: #fff;
    z-index: 1;
    overflow: hidden;
    border-radius: 12px;
     backdrop-filter: blur(15px);
  -webkit-backdrop-filter: blur(15px);
}

.pink{
    /* filter: blur(2px); */
    position: relative;
    width: 140px;
    height: 140px;
    bottom: 50px;
    left: 60px;
    background: rgba(255, 0, 128);
    z-index: -1;
    border-radius: 12px;
}

.blue{
    /* filter: blur(2px); */
    position: relative;
    width: 140px;
    height: 140px;
    top: 50px;
    right: 70px;
    background: rgb(48, 141, 255);
    z-index: -1;
    border-radius: 50%;
    margin-top: 10px;
}

span{
    display: flex;
    align-items: center;
    font-size: 54px;
    font-weight: 300;
    margin-top: 10px;
}

.bottom {
    display: flex;
    justify-content: space-evenly;
    width: 400px;
    font-size: 18px;
    font-weight: 200;
    margin-bottom: 15px;
    padding-right: 8px;
}
